package mdn.jh.automation.devices.shelly;import org.w3c.dom.Node;import mdn.jh.automation.device.DataSinkHandler;import mdn.jh.automation.io.sink.DataSink;
public class ShellyDataSinkHandler extends DataSinkHandler{private static final long serialVersionUID=1L;private ShellyDevice device;public ShellyDataSinkHandler(ShellyDevice d){device=d;}public ShellyDataSinkHandler(ShellyDevice d,Node n)throws Exception{device=d;initDataComponent(n);for(DataSink s:myDataSinks)((ShellyDataSink)s).setDevice(d);}@Override protected String getDataSinkDetail(){return device.getName();}}
